def registerCustomer(email, name, newsletter=0):
    if not isEmail(email):
        return -1
    if db.getCustomerByEmail(email) != None:
        return -2
    rec = {'email': email.lower(), 'name': toTitleCase(name), 'newsletter': newsletter,
           'spend': 0.0, 'addresses': []}
    return db.insert('customers', rec)
